import{_ as o,o as a,c as l,a2 as e}from"./chunks/framework.Crpw6aS5.js";const d=JSON.parse('{"title":"所罗门兄弟危机 Salomon Crisis","description":"1991年巴菲特临危受命，担任所罗门兄弟临时董事长10个月，正直与勇气是最好的投资","frontmatter":{"title":"所罗门兄弟危机 Salomon Crisis","description":"1991年巴菲特临危受命，担任所罗门兄弟临时董事长10个月，正直与勇气是最好的投资"},"headers":[],"relativePath":"02_concepts/salomon-crisis.md","filePath":"02_concepts/salomon-crisis.md"}'),i={name:"02_concepts/salomon-crisis.md"};function r(s,t,n,h,u,p){return a(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="所罗门兄弟危机-salomon-crisis" tabindex="-1">所罗门兄弟危机 Salomon Crisis <a class="header-anchor" href="#所罗门兄弟危机-salomon-crisis" aria-label="Permalink to &quot;所罗门兄弟危机 Salomon Crisis&quot;">​</a></h1><blockquote><p>1991年，伯克希尔投资7亿美元的所罗门兄弟濒临崩溃。巴菲特临危受命，担任临时董事长。这是他投资生涯中最不寻常的10个月，也是理解&quot;正直与声誉&quot;价值的最佳案例。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1991年/翻译.html">1991年翻译</a></strong></td><td style="text-align:left;">危机全程与处理方式</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1992年/翻译.html">1992年翻译</a></strong></td><td style="text-align:left;">危机解除，所罗门重建</td></tr></tbody></table><hr><h2 id="一、危机的本质" tabindex="-1">一、危机的本质 <a class="header-anchor" href="#一、危机的本质" aria-label="Permalink to &quot;一、危机的本质&quot;">​</a></h2><p>所罗门兄弟（Salomon Inc.）是美国最大的投资银行之一，1991年陷入了严重的法律和信任危机：</p><p><strong>核心问题</strong>：所罗门兄弟的交易员（莫泽尔）长期操纵美国国债拍卖，违反了联邦法律。这不仅是犯罪行为，更威胁到公司的生存执照。</p><p>巴菲特的判断：</p><blockquote><p>&quot;所罗门的危机不是财务危机，而是正直危机。&quot;</p></blockquote><hr><h2 id="二、为什么巴菲特选择介入" tabindex="-1">二、为什么巴菲特选择介入 <a class="header-anchor" href="#二、为什么巴菲特选择介入" aria-label="Permalink to &quot;二、为什么巴菲特选择介入&quot;">​</a></h2><p>巴菲特在1991年信中解释了为什么他愿意出面：</p><blockquote><p>&quot;所罗门有12,000名员工，他们不应该因为少数人的错误而失去生计。更重要的是，所罗门的客户和债券持有人有权期待这家公司继续运营下去。&quot;</p></blockquote><p>他接任临时董事长时，明确了三个条件：</p><ol><li>全面披露所有问题，不隐瞒</li><li>修复合规体系，确保不再发生</li><li>重建正直文化</li></ol><hr><h2 id="三、核心原则-正直、勇气是救公司最重要的东西" tabindex="-1">三、核心原则：&quot;正直、勇气是救公司最重要的东西&quot; <a class="header-anchor" href="#三、核心原则-正直、勇气是救公司最重要的东西" aria-label="Permalink to &quot;三、核心原则：&quot;正直、勇气是救公司最重要的东西&quot;&quot;">​</a></h2><p>巴菲特在1991年信中写道：</p><blockquote><p>&quot;正直、勇气是救公司最重要的东西。&quot;</p></blockquote><p>这句话后来成为伯克希尔文化的核心原则。</p><p>他进一步解释：</p><ul><li>正直意味着完全透明，不欺骗任何人（客户、监管机构、股东）</li><li>勇气意味着面对问题不退缩，不为了短期利益掩盖长期风险</li><li>两者缺一不可：没有正直的勇气是鲁莽，没有勇气的正直是无能</li></ul><hr><h2 id="四、危机处理的方法论" tabindex="-1">四、危机处理的方法论 <a class="header-anchor" href="#四、危机处理的方法论" aria-label="Permalink to &quot;四、危机处理的方法论&quot;">​</a></h2><p>巴菲特处理所罗门危机的方式，是他管理哲学的集中体现：</p><p><strong>第一步：完全透明</strong></p><ul><li>主动向美联储和财政部披露所有问题</li><li>不试图掩盖或最小化</li><li>&quot;好消息可以等，坏消息必须立刻说&quot;</li></ul><p><strong>第二步：修复问题根源</strong></p><ul><li>不是简单地炒掉肇事者，而是重建整个合规体系</li><li>认识到这是系统性问题，而非个人问题</li></ul><p><strong>第三步：保护无辜者</strong></p><ul><li>12,000名员工中绝大多数是无辜的</li><li>他们的生计和声誉不应被少数人的错误毁掉</li></ul><hr><h2 id="五、1992年的最终结果" tabindex="-1">五、1992年的最终结果 <a class="header-anchor" href="#五、1992年的最终结果" aria-label="Permalink to &quot;五、1992年的最终结果&quot;">​</a></h2><p>1992年，所罗门危机正式解除。巴菲特写道：</p><blockquote><p>&quot;1992年，我们的所罗门优先股已经被回购。加上我们出售的股份，总共收回了约1.18亿美元，我们的投资成本约为7,000万美元。&quot;</p></blockquote><p>更重要的是，所罗门的声誉得到了恢复：</p><blockquote><p>&quot;在公司声誉改善程度排名中（311家公司），所罗门排名第二。&quot;</p></blockquote><hr><h2 id="六、对投资哲学的影响" tabindex="-1">六、对投资哲学的影响 <a class="header-anchor" href="#六、对投资哲学的影响" aria-label="Permalink to &quot;六、对投资哲学的影响&quot;">​</a></h2><p>所罗门危机强化了巴菲特对&quot;声誉&quot;价值的看法：</p><ol><li><strong>声誉是商业的命脉</strong>：一次丑闻可以摧毁数十年建立的信任</li><li><strong>正直是最好的保险</strong>：预防问题比处理问题更便宜</li><li><strong>短期利益永远不值得牺牲长期声誉</strong>：所罗门的交易员为了短期奖金，毁掉了公司和自己</li><li><strong>正直+勇气 = 可信赖</strong>：只有正直没有勇气是软弱的，只有勇气没有正直是危险的</li></ol><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./reputation.html">声誉 Reputation</a> — 建立需20年，毁掉只需5分钟</li><li><a href="./management.html">管理层选择 Management</a> — 正直的管理层是优质企业的标配</li><li><a href="./risk.html">风险与回报 Risk</a> — 声誉风险的代价往往是致命的</li></ul>',46)])])}const q=o(i,[["render",r]]);export{d as __pageData,q as default};
